from itertools import product
from collections import Counter

# Явно синтетический датасет: 200 учеников, по 100 в каждом классе.
names = ['attendance','homework','activity']
probabilities = {'хорошо': [.8,.6,.5], 'плохо': [.2,.4,.5]}
data = []
for label, probabilities_in_class in probabilities.items():
    for values in product([0,1], repeat=3):
        count = 100
        for value,p in zip(values,probabilities_in_class):
            count *= p if value else 1-p
        data.extend([(*values,label)]*round(count))
assert len(data) == 200
counts = Counter(row[-1] for row in data)
print('Классы:', dict(counts))
for j,name in enumerate(names):
    for label in counts:
        selected = [r for r in data if r[-1] == label]
        positive = sum(r[j] for r in selected)
        baseline = counts[label]/len(data)
        with_feature = [r for r in data if r[j] == 1]
        conditional = sum(r[-1] == label for r in with_feature)/len(with_feature)
        print(name, label, 'n=', positive, 'P(B|класс)=', round(positive/len(selected),3), 'P(класс|B)=', round(conditional,3), 'delta=', round(abs(conditional-baseline),3))

def classify(values):
    scores = {}
    for label,count in counts.items():
        score = count/len(data)
        selected = [r for r in data if r[-1] == label]
        for j,value in enumerate(values):
            score *= sum(r[j] == value for r in selected)/count
        scores[label] = score
    total = sum(scores.values())
    normalized = {label:score/total for label,score in scores.items()}
    assert abs(sum(normalized.values())-1) < 1e-12
    return max(normalized,key=normalized.get), {k:round(v,4) for k,v in normalized.items()}

for values in [(1,1,1),(0,0,0),(1,0,1)]:
    print(values, classify(values))
